349	        registerBag("BAG1", List.of("LEG1"));
350	        load("LEG1", 1, List.of("BAG1"));
351	        seal("LEG1", 2);
352	        diffArrive("LEG1", 3, List.of()).andExpect(status().isOk());
353	
354	        // 同参重放原结果
355	        String requestId = UUID.randomUUID().toString();
356	        postJson("/api/bags/recover", Map.of("requestId", requestId,
357	                "bagTag", "BAG1", "missingLegId", "LEG1", "actualStation", "SHA"))
358	                .andExpect(status().isOk())
359	                .andExpect(jsonPath("$.status").value("DELIVERED"));
360	        postJson("/api/bags/recover", Map.of("requestId", requestId,
361	                "bagTag", "BAG1", "missingLegId", "LEG1", "actualStation", "SHA"))
362	                .andExpect(status().isOk())
363	                .andExpect(jsonPath("$.status").value("DELIVERED"));
364	        // 事件只追加一次
365	        Integer eventCount = jdbcTemplate.queryForObject(
366	                "SELECT COUNT(*) FROM bag_event WHERE bag_tag = 'BAG1' AND event_type = 'RECOVERED'",
367	                Integer.class);
368	        assertThat(eventCount).isEqualTo(1);
369	        Integer logs = jdbcTemplate.queryForObject(
370	                "SELECT COUNT(*) FROM request_log WHERE request_id = ?", Integer.class, requestId);
371	        assertThat(logs).isEqualTo(1);
372	
373	        // 同 requestId 改站 -> 409
374	        postJson("/api/bags/recover", Map.of("requestId", requestId,
375	                "bagTag", "BAG1", "missingLegId", "LEG1", "actualStation", "CAN"))
376	                .andExpect(status().isConflict());
377	
378	        // 失败不占键：短卸行李先以错误站失败（422），再用同键正确参数成功
379	        registerLeg("LEG3", "PEK", "SHA");
380	        registerBag("BAG3", List.of("LEG3"));
381	        load("LEG3", 1, List.of("BAG3"));
382	        seal("LEG3", 2);
383	        diffArrive("LEG3", 3, List.of()).andExpect(status().isOk());
384	
385	        String retryKey = UUID.randomUUID().toString();
386	        postJson("/api/bags/recover", Map.of("requestId", retryKey,
387	                "bagTag", "BAG3", "missingLegId", "LEG3", "actualStation", "CAN"))
388	                .andExpect(status().isUnprocessableEntity());
389	        postJson("/api/bags/recover", Map.of("requestId", retryKey,
390	                "bagTag", "BAG3", "missingLegId", "LEG3", "actualStation", "SHA"))
391	                .andExpect(status().isOk())
392	                .andExpect(jsonPath("$.status").value("DELIVERED"));
393	    }
394	
395	    @Test
396	    void concurrentRecoverAndLoad_consistentOrdering() throws Exception {
397	        registerLeg("LEG1", "PEK", "SHA");
398	        registerLeg("LEG2", "SHA", "CAN");
399	        registerBag("BAG_SHORT", List.of("LEG1", "LEG2"));
400	        registerBag("BAG_OK", List.of("LEG2"));
401	        load("LEG1", 1, List.of("BAG_SHORT"));
402	        seal("LEG1", 2);
403	        diffArrive("LEG1", 3, List.of()).andExpect(status().isOk());
404	
405	        // 补到与后续航段批量装载真实并发：顺序只能是“装载失败整批不移动”或“补到先提交后装载成功”
406	        List<Callable<Object>> tasks = List.of(
407	                () -> baggageService.recover(new RecoverRequest(
408	                        UUID.randomUUID().toString(), "BAG_SHORT", "LEG1", "SHA")),
409	                () -> baggageService.load("LEG2",
410	                        new LoadRequest(UUID.randomUUID().toString(), 1,
411	                                List.of("BAG_OK", "BAG_SHORT"))));
412	        List<Object> results = runConcurrently(tasks);
413	
414	        boolean loadSucceeded = results.stream()
415	                .anyMatch(r -> r instanceof com.example.starter.baggage.BaggageDtos.LoadResponse);
416	        boolean loadFailed = results.stream()
417	                .filter(ApiException.class::isInstance)
418	                .map(ApiException.class::cast)
419	                .anyMatch(ex -> ex.getStatus().value() == 422);
420	        assertThat(loadSucceeded).isNotEqualTo(loadFailed);
421	
422	        Integer okLoaded = jdbcTemplate.queryForObject(
423	                "SELECT COUNT(*) FROM load_record WHERE bag_tag = 'BAG_OK'", Integer.class);
424	        if (loadSucceeded) {
425	            // 补到先提交：整批两件都进入清单
426	            assertThat(okLoaded).isEqualTo(1);
427	            Integer shortLoaded = jdbcTemplate.queryForObject(
428	                    "SELECT COUNT(*) FROM load_record WHERE bag_tag = 'BAG_SHORT'", Integer.class);
429	            assertThat(shortLoaded).isEqualTo(1);
430	            String shortStatus = jdbcTemplate.queryForObject(
431	                    "SELECT status FROM bag WHERE bag_tag = 'BAG_SHORT'", String.class);
432	            assertThat(shortStatus).isEqualTo("RECOVERED");
433	        } else {
434	            // 装载先尝试且失败：整批不移动，补到完成后再装载必然成功
435	            assertThat(okLoaded).isZero();
436	            recover("BAG_SHORT", "LEG1", "SHA").andExpect(status().isOk());
437	            load("LEG2", 1, List.of("BAG_OK", "BAG_SHORT")).andExpect(status().isOk());
438	        }
439	    }
440	
441	    private void registerLeg(String legId, String origin, String destination) {
442	        baggageService.registerLeg(
443	                new RegisterLegRequest(UUID.randomUUID().toString(), legId, origin, destination));
444	    }
445	
446	    private void registerBag(String bagTag, List<String> legIds) {
447	        baggageService.registerBag(new RegisterBagRequest(UUID.randomUUID().toString(), bagTag, legIds));
448	    }
449	
450	    private ResultActions load(String legId, int expectedVersion, List<String> bagTags) throws Exception {
451	        return postJson("/api/legs/" + legId + "/load", Map.of(
452	                "requestId", UUID.randomUUID().toString(),
453	                "expectedVersion", expectedVersion, "bagTags", bagTags));
454	    }
455	
456	    private ResultActions seal(String legId, int expectedVersion) throws Exception {
457	        return postJson("/api/legs/" + legId + "/seal", Map.of(
458	                "requestId", UUID.randomUUID().toString(), "expectedVersion", expectedVersion));
459	    }
460	
461	    private ResultActions arriveExact(String legId, List<String> bagTags) throws Exception {
462	        return postJson("/api/legs/" + legId + "/arrive", Map.of(
463	                "requestId", UUID.randomUUID().toString(), "bagTags", bagTags));
464	    }
465	
466	    private ResultActions diffArrive(String legId, int expectedVersion, List<String> bagTags) throws Exception {
467	        return postJson("/api/legs/" + legId + "/arrive-difference", Map.of(
468	                "requestId", UUID.randomUUID().toString(),
469	                "expectedVersion", expectedVersion, "bagTags", bagTags));
470	    }
471	
472	    private ResultActions recover(String bagTag, String missingLegId, String actualStation) throws Exception {
473	        return postJson("/api/bags/recover", Map.of(
474	                "requestId", UUID.randomUUID().toString(),
475	                "bagTag", bagTag, "missingLegId", missingLegId, "actualStation", actualStation));
476	    }
477	
478	    private ResultActions postJson(String url, Object body) throws Exception {
479	        return mockMvc.perform(post(url)
480	                .contentType(MediaType.APPLICATION_JSON)
481	                .content(objectMapper.writeValueAsString(body)));
482	    }
483	
484	    /** 同步起跑并发执行任务，结果按提交顺序返回（异常包装为返回值）。 */
485	    private List<Object> runConcurrently(List<Callable<Object>> tasks) throws Exception {
486	        CountDownLatch ready = new CountDownLatch(tasks.size());
487	        CountDownLatch start = new CountDownLatch(1);
488	        List<Future<Object>> futures = new ArrayList<>();
489	        for (Callable<Object> task : tasks) {
490	            futures.add(executor.submit(() -> {
491	                ready.countDown();
492	                assertThat(start.await(10, TimeUnit.SECONDS)).isTrue();
493	                try {
494	                    return task.call();
495	                } catch (ApiException ex) {
496	                    return ex;
497	                }
498	            }));
499	        }
500	        assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
501	        start.countDown();
502	        List<Object> results = new ArrayList<>();
503	        for (Future<Object> future : futures) {
504	            results.add(future.get(30, TimeUnit.SECONDS));
505	        }
506	        return results;
507	    }
508	}
